arguments.command:
python3 -c "
import parse

fmt = '''
            letters: {:w}
            non-letters: {:W}
            whitespace: \"{!s}\"
            non-whitespace: \\t{:S}\\n
            digits: {:d}
            non-digits: {:D}
            numbers with thousands: {:n}
            fixed-point: {:f}
            floating-point: {:e}
            general numbers: {:g} {:g}
            binary: {:b}
            octal: {:o}
            hex: {:x}
'''

text = '''
            letters: abcdef_GHIJLK
            non-letters: !@#%\$ *^%
            whitespace: \"   \\t\\n\"
            non-whitespace: \\tabc\\n
            digits: 0xabcdef
            non-digits: abcdef
            numbers with thousands: 1.000.000
            fixed-point: 0.00001
            floating-point: NAN
            general numbers: 1.1e10 nan
            binary: 0B1000
            octal: 0O1000
            hex: 0X1000
'''

p = parse.Parser(fmt)
print('Fixed fields:', p._fixed_fields)
print('Type conversions:')
for k, v in sorted(p._type_conversions.items()):
    print(f'  {k}: {v}')

m = p._search_re.search(text)
if m:
    print()
    print('Number of groups:', len(m.groups()))
    for i in range(min(len(m.groups()) + 2, 25)):
        try:
            val = m.group(i)
            print(f'Group {i}: {val!r}')
        except IndexError:
            print(f'Group {i}: IndexError')
"
